return ['domain'=>'zinn-chat','plural-forms'=>'nplurals=4; plural=((((n >= 2 && n <= 4)) && ((0 == 0))) ? 1 : ((((0 == 0)) == 0)) ? 2 : (((n == 1)) && ((0 == 0))) ? 0 : 3);','language'=>'cs_CZ','project-id-version'=>'zinn-chat','pot-creation-date'=>'2026-09-25T22:28:09+00:00','po-revision-date'=>'2026-09-25T22:28:09+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Chat'=>'Zinn® Chat','https://zinndigital.com/wordpress-plugins/zinn-chat'=>'https://zinndigital.com/wordpress-plugins/zinn-chat','A fast, privacy-respecting live chat for your website. Answers visitors with AI when you are busy, hands them to you when they need a person, and emails you anything you miss. Under 10 KB on the page and no requests at all until somebody opens it.'=>'Rychlý živý chat pro váš web, který respektuje soukromí. Odpovídá návštěvníkům pomocí umělé inteligence, když jste zaneprázdněni, předá vám je, když potřebují živou osobu, a zašle vám e-mailem vše, co zmeškáte. Na stránce zabírá méně než 10 KB a neodesílá žádné požadavky, dokud jej někdo neotevře.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Settings'=>'Nastavení','That does not look like a Zinn® Chat key. Copy it from the Live chat page of your Zinn Digital® dashboard — it starts with zc_.'=>'To nevypadá jako klíč pro Zinn® Chat. Zkopírujte jej ze stránky Živý chat na svém panelu Zinn Digital® – začíná na zc_.','Add your chat key before switching the chat on — without it there is nothing for the widget to connect to.'=>'Před zapnutím chatu přidejte svůj chatovací klíč – bez něj se widget nemá k čemu připojit.','Live chat for this site. Visitors get an answer straight away, you get anything you miss by email, and the whole thing is under 10 KB on the page.'=>'Živý chat pro tento web. Návštěvníci získají odpověď okamžitě, to, co zmeškáte, dostanete e-mailem a celé to má na stránce méně než 10 KB.','The chat is live on this site.'=>'Na této stránce probíhá živý chat.','The chat is switched off. Nothing is loaded on your site.'=>'Chat je vypnutý. Na vašem webu se nic načítá.','Chat key'=>'Klíč chatu','Copy this from the Live chat page of your %s.'=>'Zkopírujte toto ze stránky Živého chatu vašeho %s.','Zinn Digital® dashboard'=>'Řídicí panel Zinn Digital®','Show the chat'=>'Zobrazit chat','Show the chat window to visitors of this site'=>'Zobrazit okno chatu návštěvníkům tohoto webu','Until you tick this, the plugin adds nothing at all to your pages — no script, no cookie, no requests.'=>'Dokud toto nezaškrtnete, plugin do vašich stránek nepřidá vůbec nic – žádný skript, žádné soubory cookie ani žádné požadavky.','%s — guides and services'=>'%s – návody a služby','User guides'=>'Uživatelské příručky','Read the %s user guide'=>'Přečtěte si uživatelskou příručku %s','Hide this'=>'Skrýt toto','Zinn® hosting for WordPress'=>'Zinn® hosting pro WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, denní zálohy, bezplatná migrace a ovládací panel vytvořený pro lidi, kteří spravují více než jeden web.','The Zinn® marketplace'=>'Tržiště Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte a prodávejte zaběhnuté weby, domény a umístění odkazů. Peníze jsou bezpečně uloženy, dokud nejsou obě strany spokojené.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — najměte si lidi, kteří se tím živí','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Naše globální tržiště pro nezávislé profesionály: procházejte více než 10 000 hotových služeb od spisovatelů, designérů, vývojářů a SEO specialistů, nebo zveřejněte projekt a nechte je přihazovat.','See the Zinn Digital® release notes.'=>'Podívejte se na poznámky k vydání Zinn Digital®.','The downloaded update failed its integrity check and was not installed.'=>'Stažená aktualizace neprošla kontrolou integrity a nebyla nainstalována.','Everything here keeps working for nothing, for ever. Pro is for when one person answering, and a month of history, stops being enough.'=>'Všechno zde funguje dál zdarma a navěky. Pro je pro chvíli, kdy jedna odpovídající osoba a měsíc historie přestanou stačit.','As many colleagues answering at once as you like — the free plugin allows one.'=>'Tolik kolegů odpovídající najednou, kolik chcete – bezplatný plugin umožňuje jednoho.','Every conversation kept for ever, instead of thirty days.'=>'Každá konverzace uchovávaná navždy namísto třiceti dnů.','Your own name on the chat window, with ours removed.'=>'Vaše vlastní jméno v okně chatu, přičemž naše bylo odstraněno.','Saved replies, transfer a conversation to a colleague, and business hours.'=>'Uložené odpovědi, předání konverzace kolegovi a pracovní doba.','5,000 AI answers a month rather than 100.'=>'5 000 odpovědí od umělé inteligence za měsíc namísto 100.','Choose exactly which pages the chat appears on — or hide it from the checkout.'=>'Vyberte přesně, na kterých stránkách se chat zobrazí – nebo jej skryjte na pokladně.','One licence covers three of your sites; ten-site licences are available.'=>'Jedna licence pokrývá tři vaše weby; k dispozici jsou desetisícové licence.','See what Pro costs'=>'Podívejte se, kolik stojí Pro','Already host a site with Zinn Digital®? Pro is included free — your key is on the %s.'=>'Hostujete již stránky u Zinn Digital®? Verze Pro je v ceně zdarma – svůj klíč najdete na %s.','Licences page of your dashboard'=>'Stránka s licencemi na vašem panelu','Your licence is active.'=>'Vaše licence je aktivní.','Your licence has run out but everything still works for a short while. Renew it to keep receiving updates.'=>'Vaše licence vypršela, ale všechno ještě chvíli funguje. Obnovte ji, abyste nepřišli o aktualizace.','We do not recognise that licence key. Copy it again from the Licences page of your Zinn Digital® dashboard.'=>'Tento licenční klíč nepoznáváme. Zkopírujte jej znovu ze stránky Licence v řídicím panelu Zinn Digital®.','That key is for a different Zinn® plugin. The one you want is on the Licences page of your dashboard, next to Zinn® Chat Pro.'=>'Tento klíč patří k jinému pluginu Zinn®. Ten, který hledáte, se nachází na stránce Licences vašeho panelu vedle Zinn® Chat Pro.','Your licence has expired. Renew it from your Zinn Digital® dashboard to switch the Pro features back on.'=>'Vaše licence vypršela. Obnovte ji na svém panelu Zinn Digital®, abyste opět zapnuli funkce Pro.','This licence has been cancelled.'=>'Tato licence byla zrušena.','This licence is on hold. Please get in touch and we will sort it out.'=>'Tato licence je pozastavena. Prosím, ozvěte se nám a my to vyřešíme.','There is a billing problem on your Zinn Digital® account. Once it is settled the licence works again straight away.'=>'Na vašem účtu Zinn Digital® se vyskytl problém s fakturací. Jakmile bude vyřešen, licence bude opět okamžitě fungovat.','This licence came free with your Zinn® hosting, and that hosting has ended. Buy a licence, or start hosting with us again, to switch Pro back on.'=>'Tato licence byla zdarma k vašemu hostingu Zinn® a tento hosting skončil. Chcete-li funkci Pro znovu zapnout, zakupte si licenci nebo u nás opět začněte hostovat.','Every site on this licence is in use. Release one below, or upgrade to cover more sites.'=>'Každý web v rámci této licence je využíván. Uvolněte některý níže, nebo přejděte na vyšší verzi, abyste mohli pokrýt více webů.','We could not confirm your licence just now. Nothing has changed on your site; we will try again shortly.'=>'Vaši licenci se nám právě nepodařilo ověřit. Na vašem webu se nic nezměnilo; brzy to zkusíme znovu.','You do not have permission to manage licences on this site.'=>'Nemáte oprávnění ke správě licencí na tomto webu.','Your Pro licence'=>'Vaše licence Pro','Licence key'=>'Licenční klíč','Copy it from the Licences page of your %s.'=>'Zkopírujte ho ze stránky Licence vašeho %s.','Renews on %s.'=>'Obnovuje se dne %s.','Using %1$d of %2$d sites.'=>'Používá se %1$d z %2$d webů.','In use on: %s. Release one from your dashboard, then try again.'=>'Používá se na: %s. Uvolněte jeden ze své nástěnky a zkuste to znovu.','Save licence'=>'Uložit licenci','Remove it from this site'=>'Odebrat z tohoto webu','Where the chat appears'=>'Kde se chat zobrazuje','Show it'=>'Zobrazit','Everywhere on this site'=>'Všude na tomto webu','Only on the pages I choose below'=>'Pouze na stránkách, které vyberu níže','Everywhere except the pages I choose below'=>'Všude kromě stránek, které vyberu níže','Page or post IDs'=>'ID stránek nebo příspěvků','Separate them with commas. The ID is in the address bar while you edit a page.'=>'Oddělte je čárkami. ID najdete v adresním řádku při úpravě stránky.','Whole content types'=>'Všechny typy obsahu','Signed-in visitors'=>'Přihlášení návštěvníci','Hide the chat from people who are signed in to this site'=>'Skrýt chat pro uživatele přihlášené k tomuto webu','Save where it appears'=>'Uložit tam, kde se nachází']];